<script setup lang="ts">
import { nextTick, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../services/api'
import { errorMessage } from '../services/http'
import { contentVersion, latestPosts, refreshCommunity } from '../composables/community'
import { user } from '../composables/session'
import type { Comment, Post } from '../types/api'
import { displayName, timeLabel, validText } from '../utils/format'
import InkAvatar from '../components/InkAvatar.vue'
import InkDialog from '../components/InkDialog.vue'
import FollowButton from '../components/FollowButton.vue'
import PostActions from '../components/PostActions.vue'
const route = useRoute(), router = useRouter(), id = Number(route.params.id)
const post = ref<Post | null>(null), error = ref(''), loading = ref(false), comments = ref<Comment[]>([]), commentCursor = ref<string | null>(null), commentsLoading = ref(false), commentsError = ref(''), commentsReady = ref(false), commentText = ref(''), sending = ref(false), sendError = ref('')
const edit = ref(false), remove = ref(false), title = ref(''), content = ref(''), busy = ref(false), actionError = ref('')
async function load() {
  loading.value = true; error.value = ''
  if (!Number.isSafeInteger(id) || id < 1) { error.value = '帖子地址无效。'; loading.value = false; return }
  try { post.value = (await api.post(id)).data; void loadComments(true) } catch (e) { error.value = errorMessage(e) } finally { loading.value = false }
}
async function loadComments(reset = false) { if (commentsLoading.value) return; commentsLoading.value = true; commentsError.value = ''; try { const result = await api.comments(id, reset ? undefined : commentCursor.value); comments.value = [...new Map([...(reset ? [] : comments.value), ...result.data].map(c => [c.id, c])).values()]; commentCursor.value = result.meta.next_cursor; commentsReady.value = true; if (route.hash === '#comments') { await nextTick(); document.getElementById('comments')?.scrollIntoView() } } catch (e) { commentsError.value = errorMessage(e) } finally { commentsLoading.value = false } }
async function sendComment() {
  if (sending.value || !post.value) return
  if (!validText(commentText.value, 2000)) { sendError.value = '评论需为 1–2000 个字符，不能只有空白。'; return }
  sending.value = true; sendError.value = ''
  try { const result = await api.comment(id, commentText.value.trim()); comments.value = [result.data, ...comments.value]; post.value.comment_count++; commentText.value = '' }
  catch (e) { sendError.value = errorMessage(e) + ' 若提交时连接中断，请先刷新评论，确认是否已经发布。' } finally { sending.value = false }
}
function startEdit() { if (!post.value) return; title.value = post.value.title; content.value = post.value.content; actionError.value = ''; edit.value = true }
async function saveEdit() { if (busy.value) return; if (!validText(title.value, 120) || !validText(content.value, 10000)) { actionError.value = '标题需为 1–120 个字符，正文需为 1–10000 个字符。'; return }; busy.value = true; actionError.value = ''; try { post.value = (await api.editPost(id, { title: title.value.trim(), content: content.value.trim() })).data; edit.value = false; contentVersion.value++; void refreshCommunity().catch(() => {}) } catch (e) { actionError.value = errorMessage(e) } finally { busy.value = false } }
async function deletePost() { if (busy.value) return; busy.value = true; actionError.value = ''; try { await api.deletePost(id); latestPosts.value = latestPosts.value.filter(p => p.id !== id); contentVersion.value++; remove.value = false; await router.replace('/me') } catch (e) { actionError.value = errorMessage(e) } finally { busy.value = false } }
onMounted(load)
</script>
<template><p v-if="loading" class="state-block" role="status">正在展开分享……</p><div v-if="error" class="state-block" role="alert"><p>{{ error }}</p><button class="secondary" @click="load">重试</button><RouterLink class="link-button" to="/">返回发现</RouterLink></div><article v-if="post" class="post-detail"><div class="detail-head"><RouterLink class="post-head" :to="`/users/${encodeURIComponent(post.author.username)}`"><InkAvatar :name="displayName(post.author)" /><span class="detail-author">{{ displayName(post.author) }}</span></RouterLink><FollowButton v-if="post.author.id !== user?.id" :id="post.author.id" :name="displayName(post.author)" :following="post.author.following" @change="post.author.following = $event" /></div><h1 class="post-title">{{ post.title }}</h1><p class="detail-meta">{{ timeLabel(post.created_at) }}<span v-if="post.edited_at"> · 已编辑</span></p><div class="detail-text">{{ post.content }}</div><PostActions :post="post" @change="post = $event" /><div v-if="post.author.id === user?.id" class="inline-actions"><button class="link-button" @click="startEdit">编辑帖子</button><button class="link-button" @click="remove = true; actionError = ''">删除帖子</button></div><section id="comments" class="comment-section"><h3>聊聊你的想法 · {{ post.comment_count }}</h3><form class="comment-form" @submit.prevent="sendComment"><label class="form-field"><span>写下评论</span><textarea v-model="commentText" required maxlength="4000" :disabled="sending" placeholder="友善交流，让分享有回响" /></label><p v-if="sendError" class="inline-error" role="alert">{{ sendError }}</p><div class="inline-actions"><button class="primary" :disabled="sending">{{ sending ? '正在发送…' : '发送评论' }}</button><button type="button" class="link-button" :disabled="commentsLoading || sending" @click="loadComments(true)">刷新评论</button></div></form><article v-for="c in comments" :key="c.id" class="comment"><InkAvatar :name="c.author.username" /><div><RouterLink :to="`/users/${encodeURIComponent(c.author.username)}`"><strong>{{ c.author.username }}</strong></RouterLink><p class="post-content">{{ c.content }}</p><span class="comment-meta">{{ timeLabel(c.created_at) }}</span></div></article><p v-if="commentsLoading" class="hint" role="status">正在加载评论……</p><div v-if="commentsError" class="state-block" role="alert"><p>{{ commentsError }}</p><button class="secondary" @click="loadComments(!commentsReady)">重试</button></div><p v-else-if="commentsReady && !comments.length" class="hint">还没有评论，来分享第一个想法吧。</p><button v-if="commentCursor" class="secondary more-posts" :disabled="commentsLoading" @click="loadComments()">更多评论</button></section></article><InkDialog :open="edit" title="修改这篇分享" label-id="edit-post-title" @close="edit = false"><form @submit.prevent="saveEdit"><label class="form-field"><span>帖子标题</span><input v-model="title" required maxlength="240" :disabled="busy" /></label><label class="form-field"><span>分享内容</span><textarea v-model="content" required maxlength="20000" :disabled="busy" /></label><p v-if="actionError" class="inline-error" role="alert">{{ actionError }}</p><button class="primary" :disabled="busy">{{ busy ? '正在保存…' : '保存修改' }}</button></form></InkDialog><InkDialog :open="remove" title="删除这篇分享？" label-id="delete-post-title" @close="remove = false"><p class="hint">删除后无法恢复，相关评论、点赞和收藏也会被移除。</p><p v-if="actionError" class="inline-error" role="alert">{{ actionError }}</p><div class="inline-actions"><button class="secondary" :disabled="busy" @click="remove = false">保留帖子</button><button class="primary" :disabled="busy" @click="deletePost">{{ busy ? '正在删除…' : '确认删除' }}</button></div></InkDialog></template>
